from collections import deque

def jumlah_pulau(grid):
    if not grid:
        return 0
    baris, kolom = len(grid), len(grid[0])
    jumlah = 0
    for r in range(baris):
        for c in range(kolom):
            if grid[r][c] == '1':
                jumlah += 1
                grid[r][c] = '0'
                antre = deque([(r, c)])
                while antre:
                    cr, cc = antre.popleft()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < baris and 0 <= nc < kolom and grid[nr][nc] == '1':
                            grid[nr][nc] = '0'
                            antre.append((nr, nc))
    return jumlah
